  incomingMultiplier(q,source){if(q?.extinctionDungeonBoss){if(['fossilDomain','fossilUltimate'].includes(q.extinctionAttack?.kind))return .25;if(q.fossilPlates>0)return 1;if(q.stunned>0)return 1.6;return q.phaseTwo?.9:1.25}if(q?.extinctionBoss&&['tyrantDomain','tyrantUltimate'].includes(q.extinctionAttack?.kind))return .25;if(!q?.extinctionDino)return q?.extinctionBoss&&q.exhausted?1.45:1;const guardOwner=source?.owner||P.Attributes.owner(source);if(q.dinoKind==='ankylosaur'&&guardOwner){const dx=guardOwner.x-q.x,front=Math.sign(dx)===(q.facing||1);return front?.48:1.3}const tank=P.state.enemies.find(t=>t!==q&&t.hp>0&&t.dinoKind==='ankylosaur'&&((t.guardTargetId===q.targetId&&(t.guardUntil||0)>P.state.elapsed)||Math.hypot(t.x-q.x,t.y-q.y)<210));return tank?((tank.guardTargetId===q.targetId) ? .55 : .75):1},
