  beginDungeon(e){const s=P.state,party=this.allPlayers();e.returnPlayers=party.map(p=>({slot:p.slot??0,x:p.x,y:p.y}));e.phase='dungeon';e.remaining=this.extinctionBalance.dungeonSeconds;e.dungeonCenter={x:e.x,y:e.y};e.dungeonKills=0;e.dungeonRoom=1;e.roomKills=0;e.spawnIn=.1;e.dungeonProps=P.Terrain.props.filter(o=>o.solid&&Math.hypot(o.x-e.x,o.y-e.y)<720).map(o=>({id:o.id,solid:o.solid}));for(const saved of e.dungeonProps){const prop=P.Terrain.props.find(o=>o.id===saved.id);if(prop)prop.solid=false}P.Terrain.revision++;P.Terrain.flow=null;P.Terrain.indexProps();s.enemies=s.enemies.filter(q=>!q.extinctionDino&&!q.extinctionBoss&&!q.extinctionFragment);s.danger=[];for(const [i,p] of party.entries()){p.x=e.x+(i?95:-95);p.y=e.y+145;p.inv=2}s.mode='play';if(!P.Combat?.server)P.$('#overlay').hidden=true;P.Loot.notify('ERA PERDIDA · 3 SALAS DE 5 · ELIGE UNA VENTAJA ENTRE SALAS');if(!P.Combat?.server)P.UI.hud()},
