  applyRoomChoice(e,choice){if(this.event!==e||e.phase!=='dungeonChoice')return false;const party=this.allPlayers();if(choice==='heal')for(const p of party)p.hp=Math.min(p.maxHp,p.hp+p.maxHp*.35);if(choice==='power')for(const p of party)p.extinctionDungeonPower=(p.extinctionDungeonPower||1)*1.2;if(choice==='risk'){e.tier=Math.min(3,(e.tier||1)+1);e.rewardMultiplier+=.35}e.dungeonRoom++;e.roomKills=0;e.phase='dungeon';e.spawnIn=.25;P.state.mode='play';if(!P.Combat?.server)P.$('#overlay').hidden=true;P.Loot.notify('SALA '+e.dungeonRoom+'/3 · '+({heal:'EQUIPO RECUPERADO',power:'INSTINTO DEPREDADOR',risk:'RIESGO Y BOTÍN AUMENTADOS'}[choice]||'CONTINÚA'));if(!P.Combat?.server)P.UI.hud();return true},
