// La armadura direccional de la Extinción se aplica en un único punto de daño,
// conservando las reglas de atributos, críticos y reliquias del resto del juego.
{const hurt=P.Entities.hurt;P.Entities.hurt=function(enemy,damage,push=0,source=null){damage*=P.MapEvents.incomingMultiplier(enemy,source);P.MapEvents.enemyHit(enemy,source);return hurt.call(this,enemy,damage,(enemy?.extinctionDino||enemy?.extinctionBoss)?0:push,source)}}
